<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Accounts</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>incidents</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <div class="d-flex me-4 mt-2">
            <div class="ms-auto">
                <button class="btn btn-success me-2" @click="printReport()">                           
                    <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                        <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                        <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                    </svg>
                </button>
                <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#register" @click="getRawData()">
                    <i class="bi bi-plus-square"></i>
                </button>
            </div>
        </div>

        <!-- loading spinner starts -->
        <div v-if="loading" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="incidents" :columns="columns" :options="table_option">
                            <template #actions="props">
                                <div class="actions text-center">
                                    <span class="bi bi-pencil-square text-success fs-5  me-2"
                                    @click="openEditModal(props.row)" 
                                    data-bs-toggle="modal" 
                                    :data-bs-target="'#account-edit-modal'"
                                    ></span>
                                    <span class="bi bi-eye text-primary fs-5" 
                                    data-bs-toggle="modal" 
                                    data-bs-target="#preview"
                                    @click="selectedIncident = props.row"
                                    ></span>
                                </div>                                 
                            </template>
                            
                            <template #priority="props">
                                <span class="badge" :style="`background-color:${props.row.priority.color}`">{{ props.row.priority.name }}</span>
                            </template>
                            <template #status="props">
                                <span class="badge" :class="`badge-${props.row.relation.entry.status.color}`">{{ props.row.relation.entry.status.name}}</span>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <!-- register and edit modal starts -->
    <div class="modal fade mymodal" id="register" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
            <div class="modal-content">
                <div class="modal-header">
                    <h1 class="modal-title fs-5" id="staticBackdropLabel">MACHINE AND VEHICLE INCIDENCE REPORTING FORM</h1>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close"></button>
                </div>
                <div class="modal-body">
                    <!-- INCIDENCE INFORMATIONS SECTION -->
                    <div class="section-header mb-3">
                        <h5 class="fw-bold">INCIDENCE INFORMATIONS</h5>
                        <hr class="section-divider">
                    </div>

                    <div class="row layout-top-spacing">
                        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                            <div class="row">
                                <div class="col-md-4">
                                    <label class="form-label">Reporter Name</label>
                                    <input v-model="formData.reporter_name" class="form-control" type="text" placeholder="Enter Reporter Name">
                                </div>

                                <div class="col-md-2">
                                    <label class="form-label">Incidence Priority </label>
                                    <multiselect 
                                        v-model="formData.priority"
                                        :options="priorities"
                                        label="name"
                                        placeholder="Select Priority"
                                        :required="false"
                                        :searchable="true"        
                                        :multiple="false"
                                        track-by="id"
                                    />
                                </div>

                                <div class="col-md-3">
                                    <label class="form-label">Select an Asset</label>
                                    <multiselect 
                                        v-model="formData.asset"
                                        :options="assets"
                                        label="name"
                                        placeholder="Select Asset"
                                        :required="false"
                                        :searchable="true"        
                                        :multiple="false"
                                        track-by="id"
                                    />
                                </div>

                                <div class="col-md-3">
                                    <label class="form-label">Incidence Reported At</label>
                                    <multiselect 
                                        v-model="formData.location"
                                        :options="locations"
                                        label="name"
                                        placeholder="Select Location"
                                        :required="false"
                                        :searchable="true"        
                                        :multiple="false"
                                        track-by="id"
                                    />
                                </div>

                                <div class="col-md-12">
                                    <label class="form-label">Incidence Description</label>
                                    <textarea v-model="formData.description" class="form-control" placeholder="Enter briefing of the incidence"></textarea>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- PROPOSED MEASURES SECTION -->
                    <div class="section-header mb-3 mt-4">
                        <h5 class="fw-bold">PROPOSED MEASURES</h5>
                        <hr class="section-divider">
                    </div>

                    <div class="measures-container">
                        <div class="row">
                            <div class="col-12 mb-3">
                                <div class="d-flex justify-content-between align-items-center">
                                    <small class="text-muted">{{ formData.proposed_measures.length }} measure(s)</small>
                                    <button type="button" class="btn btn-sm btn-success" @click="addMeasure">
                                        <i class="bi bi-plus-circle me-1"></i>Add Measure
                                    </button>
                                </div>
                            </div>
                        </div>

                        <div class="measures-list">
                            <div v-for="(measure, index) in formData.proposed_measures" :key="index" class="measure-item mb-2">
                                <div class="d-flex gap-2 align-items-start">
                                    <span class="measure-number badge bg-secondary">{{ index + 1 }}</span>
                                    <input 
                                        v-model="formData.proposed_measures[index]" 
                                        type="text" 
                                        class="form-control" 
                                        placeholder="Enter proposed measure"
                                        @input="$event => formData.proposed_measures[index] = $event.target.value"
                                    >
                                    <button 
                                        type="button" 
                                        class="btn btn-sm btn-danger" 
                                        @click="removeMeasure(index)"
                                        :disabled="formData.proposed_measures.length === 1"
                                        title="Remove measure"
                                    >
                                        <i class="bi bi-trash"></i>
                                    </button>
                                </div>
                                <small v-if="!measure" class="text-danger ms-5">This field cannot be empty</small>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="modal-footer">
                    <button type="button" class="btn btn-danger" data-bs-dismiss="modal">Close</button>
                    <button type="button" class="btn btn-success" @click="saveIncident">Save</button>
                </div>
            </div>
        </div>
    </div>
    <!-- register and edit modal ends -->
     <!-- preview starts -->
          <div class="modal fade mymodal" id="preview" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
            <div class="modal-content">
                <div class="modal-header">
                    <h1 class="modal-title fs-5" id="staticBackdropLabel">MACHINE AND VEHICLE INCIDENT REPORTED</h1>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close"></button>
                </div>
                <div class="modal-body">
                    <!-- INCIDENCE INFORMATIONS SECTION -->
                    <div class="section-header mb-3">
                        <h5 class="fw-bold">INCIDENT INFORMATIONS</h5>
                        <hr class="section-divider">
                    </div>

                    <div class="row layout-top-spacing" v-if="selectedIncident">
                        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                            <div class="table-responsive">
                                <table class="table table-bordered mb-0 table-striped">
                                    <tbody>
                                        <tr>
                                            <th scope="row" class="w-25">Reporter Name</th>
                                            <td>{{ selectedIncident?.reporter }}</td>
                                            <th scope="row" class="w-25">Incident Priority</th>
                                            <td>
                                                <span class="badge" :style="`background-color: ${selectedIncident?.priority.color};`">
                                                    {{ selectedIncident?.priority?.name }}
                                                </span>
                                            </td>
                                        </tr>
                                        <tr>
                                            <th scope="row">Asset</th>
                                            <td>{{ selectedIncident.asset }}</td>
                                            <th scope="row">Incident Reported At</th>
                                            <td>{{ selectedIncident.location }}</td>
                                        </tr>
                                        <tr>
                                            <th scope="row">Incident Description</th>
                                            <td colspan="3">{{ selectedIncident.description }}</td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>

                    <!-- PROPOSED MEASURES SECTION -->
                    <div class="section-header mb-3 mt-4">
                        <h5 class="fw-bold">PROPOSED MEASURES </h5>
                        <!-- <hr class="section-divider"> -->
                        <ol class="list-group list-group-numbered">
  <li v-for="measure in selectedIncident?.relation?.entry?.measures" class="list-group-item">{{ measure.description }}</li>
</ol>
                    </div>

                </div>

                <div class="modal-footer">
                    <button type="button" class="btn btn-danger" data-bs-dismiss="modal">Close</button>
                </div>
            </div>
        </div>
    </div>
      <!-- preview ends -->
</template>

<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'account' });  
    
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    const formatNumber = inject('formatNumber');
    const formatDate = inject('formatDate');
    const selectedIncident = ref('')
    const loading_spinner = ref(false);
    const columns = ref(['Sno','ref_no','asset','issuer','reporter','description','detection_source','location','priority','status','date','actions']);    

    const priorities = ref([]);

    const locations = ref([]);

    const formData = ref({
        priority: null,
        location: null,
        issuer_id: JSON.parse(localStorage.getItem("user")).id,
        reporter_name: '',
        description: '',
        asset : '',
        proposed_measures: ['']
    });

    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50, 100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['Sno', 'name','email','phone','address','attachment'],        
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const incidents = ref([]);
    const loading = ref('')
    const getIncidents = async () => {
        loading.value = true
        try {
            const response = await axiosInstance.get(`incidents`);
            incidents.value = response.data.map((item, index) => ({
                ...item,
                Sno: index + 1,
                ref_no: 'INC-000' + item.id,
                asset : item.asset.name + ' - '+ item.asset.type_name,
                reporter: item.reporter_name,
                date: formatDate(item.created_at),
                issuer: item?.relation.entry.issuer?.name,
                location: item?.location?.name,
                detection_source: item.source,
                description: item.relation.entry.description,
            }));
        } catch(error) {
            showError(error.message);
            console.log(error);
        }finally{
            loading.value = false
        }
    };

        const assets = ref([])

        const getRawData = async () => {
        try {
            const response = await axiosInstance.get(`incident-raw-data`);
            assets.value = response.data.assets.map((item, index) => ({
                ...item,
               name : item.name + ' - '+ item.type_name
            }));
            priorities.value = response.data.priorities
            locations.value = response.data.locations
        } catch(error) {
            showError(error.message);
            console.log(error);
        }
    };

    const addMeasure = () => {
        formData.value.proposed_measures.push('');
    };

    const removeMeasure = (index) => {
        formData.value.proposed_measures.splice(index, 1);
    };

    const saveIncident = async () => {
        try {
            // Validate required fields
            if (!formData.value.reporter_name.trim()) {
                showError('Reporter name is required');
                return;
            }
            if (!formData.value.priority) {
                showError('Priority is required');
                return;
            }
            if (!formData.value.location) {
                showError('Location is required');
                return;
            }
            if (!formData.value.description.trim()) {
                showError('Description is required');
                return;
            }

            // Filter out empty measures
            const validMeasures = formData.value.proposed_measures.filter(m => m.trim());
            if (validMeasures.length === 0) {
                showError('At least one proposed measure is required');
                return;
            }

            const payload = {
                priority_id: formData.value.priority?.id,
                location_id: formData.value.location?.id,
                source : 'MANUAL',
                issuer_id: formData.value.issuer_id,
                reporter_name: formData.value.reporter_name,
                description: formData.value.description,
                proposed_measures: validMeasures,
                asset_id : formData.value.asset.id
            };
            // console.log(payload)
            // return 
            const response = await axiosInstance.post('incidents', payload);
            showMessage('Incident saved successfully');
            
            // Reset form
            resetForm();
            
            // Close modal
            const modal = document.getElementById('register');
            const bootstrapModal = window.bootstrap.Modal.getInstance(modal);
            bootstrapModal?.hide();
            
            // Refresh table
            await getIncidents();
        } catch(error) {
            showError(error.response?.data?.message || error.message);
            console.log(error);
        }
    };

    const resetForm = () => {
        formData.value = {
            priority: null,
            location: null,
            issuer_id: JSON.parse(localStorage.getItem("user")).id,
            reporter_name: '',
            description: '',
            proposed_measures: ['']
        };
    };

    const printReport = async () => {
        try {
            const iframe = document.createElement("iframe");
            iframe.style.display = "none";
            document.body.appendChild(iframe);

            const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Account Transaction incidents Report</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>

<div class="company-title text-style">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  ACCOUNT TRANSACTION incidents REPORT
</div>

<hr>

<table>
  <thead>
    <tr>
      <th>No.</th>
      <th>Ref NO</th>
      <th>Issuer</th>
      <th>Host</th>
      <th>Account Target</th>
      <th>Date</th>
      <th>Direction</th>
      <th class="text-right">Amount</th>
    </tr>
  </thead>
  <tbody>
    ${incidents.value.map((payment, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${payment.ref_no || 'N/A'}</td>
      <td>${payment.issuer || 'N/A'}</td>
      <td>${payment.host || 'N/A'}</td>
      <td>${payment.target_account || 'N/A'}</td>
      <td>${payment.date || 'N/A'}</td>
      <td>${payment.direction || 'N/A'}</td>
      <td class="text-right">${payment.amount || '0'}</td>
    </tr>
    `).join('')}
    <tr>
      <td colspan="7" class="text-right"><strong>TOTAL:</strong></td>
      <td class="text-right"><strong>${formatNumber(incidents.value.reduce((sum, payment) => {
        const amount = typeof payment.amount === 'string' ? parseFloat(payment.amount.replace(/,/g, '')) : payment.amount;
        return sum + (isNaN(amount) ? 0 : amount);
      }, 0))}</strong></td>
    </tr>
  </tbody>
</table>

</body>
</html>
`;

            const iframeDoc = iframe.contentWindow.document;
            iframeDoc.open();
            iframeDoc.write(printContent);
            iframeDoc.close();

            iframe.onload = () => {
                iframe.contentWindow.focus();
                iframe.contentWindow.print();
                setTimeout(() => {
                    document.body.removeChild(iframe);
                }, 1000);
            };
        } catch (error) {
            showError(`Failed to print report: ${error.message}`);
        }
    };


    onMounted(() => {
        getIncidents();
    });
</script>

<style scoped>
.section-header {
    margin-top: 2rem;
}

.section-divider {
    height: 2px;
    background-color: #333;
    margin: 0.5rem 0;
    border: none;
}

.measures-container {
    background-color: #f8f9fa;
    padding: 1.5rem;
    border-radius: 0.5rem;
    border-left: 4px solid #198754;
}

.measures-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.measure-item {
    background-color: white;
    padding: 0.75rem;
    border-radius: 0.375rem;
    border: 1px solid #e9ecef;
    transition: all 0.2s ease;
}

.measure-item:hover {
    border-color: #198754;
    box-shadow: 0 1px 3px rgba(25, 135, 84, 0.1);
}

.measure-number {
    min-width: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
}

.measure-item .form-control {
    flex: 1;
}

.measure-item .btn-danger:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.gap-2 {
    gap: 0.5rem;
}
</style>